// https://iquilezles.org/articles/distfunctions2d/
float dot2( in vec2 v ) { return dot(v,v); }
float dot2( in vec3 v ) { return dot(v,v); }
float ndot( in vec2 a, in vec2 b ) { return a.x*b.x - a.y*b.y; }
float sdHeart( in vec2 p ) {
    p.x = abs(p.x);

    if( p.y+p.x>1.0 )
        return sqrt(dot2(p-vec2(0.25,0.75))) - sqrt(2.0)/4.0;
    return sqrt(min(dot2(p-vec2(0.00,1.00)),
                    dot2(p-0.5*max(p.x+p.y,0.0)))) * sign(p.x-p.y);
}
float sdCircle( vec2 p, float r ) {
    return length(p) - r;
}
float sdStar( in vec2 p, in float r, in int n, in float m) {
    // next 4 lines can be precomputed for a given shape
    float an = 3.141593/float(n);
    float en = 3.141593/m;  // m is between 2 and n
    vec2  acs = vec2(cos(an),sin(an));
    vec2  ecs = vec2(cos(en),sin(en)); // ecs=vec2(0,1) for regular polygon

    float bn = mod(atan(p.x,p.y),2.0*an) - an;
    p = length(p)*vec2(cos(bn),abs(sin(bn)));
    p -= r*acs;
    p += ecs*clamp( -dot(p,ecs), 0.0, r*acs.y/ecs.y);
    return length(p)*sign(p.x);
}

void translate(inout vec2 uv, in vec2 v) {
    uv -= v;
}
mat2 rotate(float theta){
    return mat2(cos(theta), -sin(theta),
              sin(theta), cos(theta));
}
mat2 antiRotate(float theta){
    return mat2(cos(theta), sin(theta),
              -sin(theta), cos(theta));
}

vec3 palette( in float t ) {
    vec3 a = vec3(0.248, -0.062, 0.868);
    vec3 b = vec3(0.558, 0.500, 0.500);
    vec3 c = vec3(-0.022, -0.952, 0.468);
    vec3 d = vec3(-0.022, 0.333, -0.332);
    return a + b*cos( 6.283185*(c*t+d) );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord/iResolution.xy - 0.5) * 2.0;
    uv.x *= iResolution.x/iResolution.y;
    vec2 mouse = iMouse.xy / iResolution.xy * 2.0 - 1.0;
    mouse.x *= iResolution.x / iResolution.y;

    vec3 color = vec3(0.0);
    float len = length(uv);

    // float circle = 0.02/abs(sdCircle(uv, 0.1));
    // color += circle;
    float rr = 0.4 + 0.2 * sin(iTime * 2.0);
    float starCount = 3.0;
    for (float i = 0.0; i < starCount; ++i) {
        float theta = (iTime + i * 6.28 / starCount) * 2.0;
        // float theta = iTime;
        vec2 trans = vec2(rr * cos(theta), rr * sin(theta));
        // vec2 trans = mouse;
        translate(uv, trans);
        uv *= rotate(iTime * 5.0);
        float star = 0.005/abs(sdStar(uv, 0.1, 5, 3.5));
        color += star;
        uv *= antiRotate(iTime * 5.0);
        translate(uv, -trans);  
    }

    rr = 0.8 + 0.2 * sin(iTime * 3.0);
    starCount = 5.0;
    for (float i = 0.0; i < starCount; ++i) {
        float theta = (iTime + i * 6.28 / starCount) * -2.0;
        // float theta = iTime;
        vec2 trans = vec2(rr * cos(theta), rr * sin(theta));
        // vec2 trans = mouse;
        translate(uv, trans);
        uv *= rotate(iTime * 5.0);
        float star = 0.005/abs(sdStar(uv, 0.1, 5, 3.5));
        color += star;
        uv *= antiRotate(iTime * 5.0);
        translate(uv, -trans);  
    }

    rr = 1.4 + 0.3 * sin(iTime * 3.0);
    starCount = 7.0;
    for (float i = 0.0; i < starCount; ++i) {
        float theta = (iTime + i * 6.28 / starCount) * 2.0;
        // float theta = iTime;
        vec2 trans = vec2(rr * cos(theta), rr * sin(theta));
        // vec2 trans = mouse;
        translate(uv, trans);
        uv *= rotate(iTime * 5.0);
        float star = 0.005/abs(sdStar(uv, 0.1, 5, 3.5));
        color += star;
        uv *= antiRotate(iTime * 5.0);
        translate(uv, -trans);  
    }


    // uv *= rotate(iTime);
    translate(uv, vec2(0.0, -0.6));
    float heart = 0.08/abs(sin(sdHeart(uv) * 5.0 - iTime * 3.0));
    heart = pow(heart, 1.1);
    color += heart;

    color *= palette(len);

    fragColor = vec4(color, 1.0);
}
